import {planner, apply} from "./replay.mjs";
import {readCatalog} from "./common/limits.mjs";

const base = {service:"studio", tenant:"orchid", day:"2025-04-02"};
const book = (id, units, extra = {}) => ({...base, action:"book", id, units, ...extra});

test("Studio quota is tenant/day scoped and does not change the catalog", () => {
  const catalog = readCatalog();
  catalog.studios.set("iris", 2);
  const dispatch = planner(catalog);
  assert.deepEqual(dispatch(book("morning", 7)), {status:"booked", id:"morning", remaining:1});
  assert.deepEqual(dispatch(book("overflow", 2)), {status:"full", id:"overflow", remaining:1});
  assert.equal(dispatch(book("tomorrow", 8, {day:"2025-04-03"})).status, "booked");
  assert.equal(dispatch(book("iris", 3, {tenant:"iris"})).status, "full");
  assert.equal(dispatch(book("unlisted", 5, {tenant:"aster"})).status, "booked");
  assert.equal(dispatch(book("unlisted-full", 1, {tenant:"aster"})).status, "full");
  assert.equal(catalog.default, 5);
});

test("Studio keeps replay, conflict, cancellation and import accounting", () => {
  const dispatch = planner(readCatalog());
  const request = book("first", 8);
  assert.equal(dispatch(request).status, "booked");
  assert.equal(dispatch(request).status, "replay");
  assert.equal(dispatch({...request, units:7}).status, "conflict");
  assert.equal(dispatch({...base, action:"cancel", id:"first"}).status, "cancelled");
  assert.equal(dispatch(request).status, "cancelled");
  assert.equal(dispatch({...base, action:"cancel", id:"first"}).status, "replay");
  assert.equal(dispatch({...book("imported", 7), action:"import"}).status, "imported");
  assert.deepEqual(dispatch({...base, action:"usage"}), {units:7});
  assert.deepEqual(dispatch(book("last", 1)), {status:"booked", id:"last", remaining:0});
  const summary = dispatch({...base, action:"summary"});
  assert.deepEqual(summary.occupied.map(row => row.id), ["imported", "last"]);
  assert.equal(summary.events.length, 4);
});

test("monthly renewals use Studio allocations and preserve renewal semantics", () => {
  const dispatch = planner(readCatalog());
  dispatch(book("previous", 7));
  const renewal = {...base, action:"renew", previous:"previous", id:"next", day:"2025-05-02"};
  assert.deepEqual(dispatch(renewal), {status:"booked", id:"next", remaining:1});
  assert.equal(dispatch(renewal).status, "replay");
  assert.equal(dispatch({...renewal, units:6}).status, "conflict");
  assert.equal(dispatch({...renewal, id:"too-large", units:2}).status, "full");
  dispatch({...base, action:"cancel", id:"next"});
  assert.equal(dispatch(renewal).status, "cancelled");
  assert.equal(dispatch({...renewal, id:"replacement", units:8}).status, "booked");
  dispatch({...base, action:"cancel", id:"previous"});
  assert.deepEqual(dispatch({...renewal, id:"missing"}), {status:"missing", id:"previous"});
});

